def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    if a < 1:
        return False

    # Check if a is prime
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # If a is less than 3, it can't be product of 3 primes
    if a < 3:
        return False

    # Check if a is prime
    if is_prime(a):
        return False

    # Find prime factors
    factors = []
    d = 2
    temp = a

    while d * d <= temp:
        if temp % d == 0:
            factors.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)

    # Check if we have exactly 3 prime factors
    if len(factors) == 3:
        return True
    return False
